		s.logger.For(ctx).Error("cannot marshal response", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func (s *Server) deleteLocation(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
