package driver

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/dnwe/otelsarama"
	"github.com/signadot/hotrod/pkg/baggageutils"
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/notifications"
	"github.com/signadot/routesapi/go-routesapi"
	"github.com/signadot/routesapi/go-routesapi/watched"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/IBM/sarama"
)

type Consumer struct {
	tracer       trace.Tracer
	logger       log.Factory
	routing      watched.BaselineWatched
	driverStore  *driverStore
	bestETA      *bestETA
	notification notifications.Interface
	ready        chan bool
}

func newConsumer(ctx context.Context, tracerProvider trace.TracerProvider,
	logger log.Factory) *Consumer {
	// create a routesapi baseline watched instance
	// TODO: remove this in case we're not running with Signadot
	//
	// Virtual workloads are excluded: shouldProcess treats "no routing rule"
	// as "the baseline handles it", which is exactly what a virtual workload
	// means.
	routing, err := watched.BaselineWatchedFromEnv(&routesapi.ClientInfo{
		EnableVirtualWorkloads: false,
	})
	if err != nil {
		panic(err)
	}

	tracer := tracerProvider.Tracer("driver")
	return &Consumer{
		tracer:       tracer,
		logger:       logger,
		routing:      routing,
		driverStore:  newDriverStore(tracer, logger),
		bestETA:      newBestETA(tracerProvider, tracer, logger),
		notification: notifications.NewNotificationHandler(tracerProvider, logger),
		ready:        make(chan bool),
	}
}

func (consumer *Consumer) Setup(sarama.ConsumerGroupSession) error {
	// Mark the consumer as ready
	close(consumer.ready)
	return nil
}

func (consumer *Consumer) Cleanup(sarama.ConsumerGroupSession) error {
	return nil
}

func (consumer *Consumer) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for {
		select {
		case message, ok := <-claim.Messages():
}

func (d *dispatcher) DispatchDriver(ctx context.Context, req *DispatchRequest,
	pickupLoc, dropoffLoc *location.Location) error {
	ctx, span := d.tracer.Start(ctx, "DispatchDriver", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		attribute.
			Key("session.id").
			Int(int(req.SessionID)),
	)
	defer span.End()

	driverRequest := driver.DispatchRequest{
		PickupLocation:  pickupLoc,
		DropoffLocation: dropoffLoc,
	}
	msgBody, err := json.Marshal(driverRequest)
	if err != nil {
		return fmt.Errorf("couldn't encode driver request, %w", err)
	}

	msg := &sarama.ProducerMessage{
		Topic: kafka.DispatchDriverTopic,
		Key:   sarama.StringEncoder("message"),
		Value: sarama.StringEncoder(string(msgBody)),
	}
	otel.GetTextMapPropagator().Inject(ctx, otelsarama.NewProducerMessageCarrier(msg))

	partition, offset, err := d.producer.SendMessage(msg)
	if err != nil {
		return fmt.Errorf("couldn't publish message to kafka, %w", err)
	}

	d.logger.For(ctx).Info("Published message to kafka",
		zap.Any("pickupLocation", pickupLoc),
		zap.Any("dropoffLocation", dropoffLoc),
		zap.Any("partition", partition),
		zap.Any("offset", offset),
	)
	return nil
}
	DriverID string
	ETA      time.Duration
}

func newBestETA(tracerProvider trace.TracerProvider, tracer trace.Tracer, logger log.Factory) *bestETA {
	return &bestETA{
		tracer: tracer,
		route:  route.NewClient(tracerProvider, logger, config.GetRouteAddr()),
		pool:   pool.New(config.GetDriverWorkerPoolSize()),
		logger: logger,
	}
}

func (eta *bestETA) Get(ctx context.Context, dispatchReq *DispatchRequest,
	drivers []*Driver) (*Response, error) {
	ctx, span := eta.tracer.Start(ctx, "CalculateBestRoute", trace.WithSpanKind(trace.SpanKindClient))
	defer span.End()

	// get all routes from the drivers to the pick up location
	results := eta.getRoutes(ctx, dispatchReq.PickupLocation, drivers)
	eta.logger.For(ctx).Info("Found routes", zap.Any("routes", results))

	// search the one with the best ETA
	resp := &Response{ETA: math.MaxInt64}
	for _, result := range results {
		if result.err != nil {
			span.SetStatus(codes.Error, result.err.Error())
			return nil, result.err
		}
		if result.route.ETA < resp.ETA {
			resp.ETA = result.route.ETA
			resp.DriverID = result.driverID
		}
	}
	if resp.DriverID == "" {
		err := errors.New("no routes found")
		span.SetStatus(codes.Error, err.Error())
		return nil, err
	}

	eta.logger.For(ctx).Info("Dispatch successful",
		zap.String("driverID", resp.DriverID),
		zap.String("eta", resp.ETA.String()),
	)
	return resp, nil
}

type routeResult struct {
	driverID string
	route    *route.Route
	err      error
