async (page) => {
  await page.unrouteAll();
  globalThis.__errs = [];
  page.on('pageerror', e => globalThis.__errs.push('pageerror: ' + e.message));
  await page.route('http://frontend.ctbench-hotrod.svc:8080/**', async route => {
    await route.continue({ headers: { ...route.request().headers(), baggage: 'sd-routing-key=fzqcn698x48fl', tracestate: 'sd-routing-key=fzqcn698x48fl' } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const opts = await page.$$eval('select', ss => ss.map(s => [...s.options].map(o => `${o.value}=${o.text}`)));
  return { len: (await page.content()).length, opts, errs: globalThis.__errs };
}

