async (page) => {
  const sels = page.locator('select');
  await sels.nth(0).selectOption({ label: 'My Home' });
  await sels.nth(1).selectOption({ label: 'Amazing Coffee Roasters' });
  const btn = page.getByRole('button', { name: 'Request Ride' });
  const enabled = await btn.isEnabled();
  await btn.click();
  await page.waitForTimeout(500);
  const toast = await page.locator('[role=status], .chakra-toast, [id^=toast]').allInnerTexts();
  await page.getByRole('button', { name: 'Show Logs' }).click();
  await page.getByText(/will arrive in|arrived/).first().waitFor({ timeout: 20000 }).catch(() => {});
  await page.waitForTimeout(4000);
  const body = await page.locator('body').innerText();
  await page.screenshot({ path: '/tmp/hr/ui.png' });
  return { enabled, toast, len: (await page.content()).length, body: body.slice(0, 1500), errs: globalThis.__errs, mapRendered: await page.locator('.leaflet-container').count() };
}

