async (page) => {
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  await page.getByRole("combobox").first().selectOption("1");
  await page.getByRole("combobox").nth(1).selectOption("123");
  await page.getByRole("button", { name: "Request Ride" }).click();
  await page.getByRole('button', { name: 'Show Logs' }).click();
  const route = page.locator("//div[p[2][contains(text(), 'route')]]/p[4]");
  await route.waitFor({ timeout: 20000 });
  const r1 = await route.innerText();
  const drv = page.locator("//div[p[2][contains(text(), 'driver')]]/p[4]").last();
  await page.waitForFunction(() => /T7\d{5}C/.test(document.body.innerText), null, { timeout: 20000 });
  return { routeText: r1, driverText: await drv.innerText() };
}

